<?php $npm=$_SESSION['display_name']??'';$st=$pdo->prepare('SELECT m.*,k.nama_kelas FROM mahasiswa m LEFT JOIN kelas k ON k.id=m.kelas_id JOIN users u ON u.username=m.npm WHERE u.id=?');$st->execute([userId()]);$m=$st->fetch();$stats=[];$st=$pdo->prepare("SELECT COUNT(*) FROM absensi a JOIN mahasiswa m ON m.id=a.mahasiswa_id JOIN users u ON u.username=m.npm WHERE u.id=? AND a.status IN ('Hadir','Terlambat')");$st->execute([userId()]);$hadir=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM absensi a JOIN mahasiswa m ON m.id=a.mahasiswa_id JOIN users u ON u.username=m.npm WHERE u.id=?");$st->execute([userId()]);$total=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT s.*,mk.nama_mk,d.nama AS dosen FROM sesi_absensi s JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id JOIN dosen d ON d.id=j.dosen_id WHERE j.kelas_id=? ORDER BY s.tanggal DESC,s.id DESC LIMIT 5");$st->execute([(int)$m['kelas_id']]);$recent=$st->fetchAll();$rate=$total?round($hadir/$total*100):0; ?>
<div class="stats"><div class="stat"><small>Kehadiran</small><strong><?=$rate?>%</strong><span><?=$hadir?> hadir dari <?=$total?> catatan</span></div><div class="stat"><small>Kelas</small><strong><?=e($m['nama_kelas']??'-')?></strong><span><?=e($m['prodi']??'-')?></span></div><div class="stat"><small>QR ID</small><strong style="font-size:18px"><?=e($m['qr_code'])?></strong><span>Identitas kartu</span></div><div class="stat"><small>Verifikasi</small><strong><?= $m['face_verified_at']?'OK':'—' ?></strong><span>status identitas</span></div></div><div class="content-grid"><section class="section"><div class="section-head"><h2>Aktivitas sesi terbaru</h2><a class="btn btn-ghost" href="riwayat.php">Lihat semua</a></div><?php if(!$recent):?><div class="empty">Belum ada sesi tercatat.</div><?php else:?><div class="mini-list"><?php foreach($recent as $r): ?><div class="mini-item"><div><b><?=e($r['nama_mk'])?></b><small><?=e($r['tanggal'])?> · <?=e(substr($r['jam_mulai'],0,5))?></small></div><span class="badge <?= $r['status']==='aktif'?'green':'' ?>"><?=e(strtoupper($r['status']))?></span></div><?php endforeach;?></div><?php endif;?></section><section class="section"><div class="section-head"><h2>Akses cepat</h2></div><div class="actions"><a class="btn btn-primary" href="absensi.php">Scan & Absen</a><a class="btn btn-ghost" href="kartu.php">Buka Kartu QR</a><a class="btn btn-ghost" href="profil.php">Profil saya</a></div><div class="notice" style="margin-top:18px">Absensi akan memeriksa sesi aktif, lokasi perangkat, radius kampus, dan waktu server.</div></section></div>
